const u={ui:{fig:"Fig. 4",title:"Fond rapporté",svgLabel:"Un dessin isométrique pour coudre un fond rapporté : les parois cousues en tube, les milieux du fond et du tube repérés par des plis, le tube sur l'envers posé sur le fond, repère sur repère et maintenu par des pinces, la marge des parois crantée aux coins, le fond cousu un côté à la fois, et le sac retourné, avec un fond plat.",prev:"Étape précédente",dot:(e,t)=>e?`Étape ${e} : ${t}`:t,start:"Étapes →",next:"Suivant →",overview:"Vue d'ensemble",stepOf:(e,t)=>`Étape ${e} sur ${t}`,machine:e=>`Machine : ${e.toLowerCase()}`,inThisStep:"Pour cette étape",takeApart:"Remettre debout",putTogether:"Voir le dessous",replay:"↻ Revoir",parts:"Pièces",allSteps:"Instructions étape par étape",endView:"VUE EN COUPE"},stitches:{straight:"Point droit"},labels:{rightSides:"endroit contre endroit",bothSides:"coudre les deux côtés",aTube:"un tube ouvert aux deux bouts",foldCrease:"plier, marquer le pli",markMiddle:"un repère à chaque milieu",seamMark:"couture de côté = repère",insideOut:"sur l'envers",markOnMark:"repère sur repère",clipBetween:"puis des pinces entre",clipCorner:"cranter aux ciseaux",notThrough:"avant la ligne de couture",backstitch:"point d'arrêt",oneSide:"un côté à la fois",stopTurn:"arrêt, pivoter",allRound:"tout autour",turnOut:"retourner sur l'endroit",flatBottom:"un fond plat",baseSeam:"couture autour du fond"},steps:[{title:"Fond rapporté",text:"Le fond du sac, le sac à l'envers : le fond est une pièce à part, ici dans un autre tissu, cousue aux parois tout autour. Touchez le sac pour le remettre debout."},{title:"Coudre les parois en tube",text:"Posez le devant sur le dos, endroit contre endroit, et cousez les deux côtés : un tube, ouvert aux deux bouts. Le fond est une pièce à part.",details:["Posez le devant sur le dos, endroit contre endroit, et maintenez avec des pinces.","Cousez les deux côtés, de haut en bas.","Le tube reste ouvert en bas aussi : le fond est une pièce à part, cousue plus tard.","Si les parois sont coupées d'une seule pièce, une seule couture ferme le tube."]},{title:"Repérer les milieux",text:"Pliez le fond en deux et marquez le pli, puis pliez-le en deux dans l'autre sens : faites un repère au milieu de chaque côté. Pliez aussi le tube en deux et marquez le pli : les plis et les coutures de côté repèrent ses milieux.",details:["Pliez le fond en deux et marquez le pli au fer ou avec les doigts.","Dépliez-le, pliez-le en deux dans l'autre sens et marquez de nouveau le pli.","Faites un repère au milieu de chaque côté, sur le bord, là où arrive un pli.","Pliez le tube en deux, couture de côté sur couture de côté, et marquez le pli : les plis repèrent le milieu du devant et du dos.","Les coutures de côté sont aussi des repères : le tube est partagé en quatre, comme le fond."]},{title:"Repère sur repère",text:"Gardez le tube sur l'envers et posez-le sur le fond, endroit contre endroit, bords alignés. Placez d'abord repère sur repère, les coutures de côté et les plis sur les milieux du fond, puis posez des pinces entre les repères.",details:["Le tube est sur l'envers et le fond endroit dessus : les endroits se font face.","Alignez les bords du tube et du fond tout autour ; la marge des parois repose sur le bord du fond.","D'abord repère sur repère : chaque couture de côté au milieu d'un petit côté, chaque pli au milieu d'un grand côté.","Maintenez d'abord les repères avec des pinces, puis entre les repères."]},{title:"Cranter les coins",text:"À chaque coin du fond, crantez aux ciseaux la marge des parois droit dans le coin, jusqu'à la ligne de couture sans l'atteindre, sans couper la couture : les parois peuvent alors tourner dans l'angle.",details:["Repérez où chaque coin du fond rencontre les parois.","Crantez la marge des parois dans le coin, jusqu'à la ligne de couture sans l'atteindre : sans couper la couture.","La marge s'ouvre alors et se pose à plat autour du coin, et le coin reste net.","Crantez tous les coins de la même façon."]},{title:"Coudre le fond",text:"Cousez un côté à la fois : commencez par un point d'arrêt, arrêtez-vous à une marge de couture du coin, aiguille piquée, pivotez dans l'angle et cousez le côté suivant.",details:["Cousez avec le tube sur l'envers, sur la ligne de couture.","Commencez au milieu d'un côté, par un point d'arrêt.","Arrêtez-vous à une marge de couture du coin, aiguille piquée dans le tissu.","Relevez le pied presseur, pivotez dans l'angle, baissez le pied et cousez le côté suivant.","Retirez les pinces au fur et à mesure et faites tout le tour ; finissez par un point d'arrêt."]},{title:"Retourner",text:"Retournez le sac sur l'endroit et faites bien ressortir les coins : un fond plat, cousu aux parois tout autour.",details:["Retournez le sac sur l'endroit et faites ressortir les coins.","Le fond est bien à plat, et la couture fait le tour de son bord.","Pour un fond rigide, le renfort va sur le fond : un entoilage thermocollant posé au fer avant de le coudre, ou ensuite une plaque de fond rigide posée à l'intérieur."]}],legend:[{title:"Fond",text:"une pièce à part · ici dans un autre tissu"},{title:"Couture du fond",text:"joint les parois au fond, tout autour"},{title:"Coins",text:"marge des parois crantée, le coin reste net"},{title:"Coutures de côté",text:"chacune arrive au milieu d'un petit côté du fond"}]};export{u as default};
